create or replace function private.finalize_match_result(p_result_id uuid)returns table(result_id uuid,official_result_id uuid,calculation_version bigint,version bigint)language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare v_result public.match_results%rowtype;v_match public.matches%rowtype;v_revision public.result_revisions%rowtype;v_actor uuid:=public.current_player_id();v_official uuid;v_calc bigint;v_team_a numeric;v_team_b numeric;v_delta numeric;v_player record;v_pre numeric;v_post numeric;v_won boolean;v_stats public.player_statistics%rowtype;v_checksum text;
begin
 select * into v_result from public.match_results where id=p_result_id for update;if v_result.id is null then raise exception using errcode='P0001',detail='NOT_FOUND';end if;
 select o.id,o.calculation_version,r.version into v_official,v_calc,version from public.official_results o join public.match_results r on r.id=v_result.id where o.match_id=v_result.match_id;if v_official is not null then result_id:=v_result.id;official_result_id:=v_official;calculation_version:=v_calc;return next;return;end if;
 select * into v_match from public.matches where id=v_result.match_id for update;select * into v_revision from public.result_revisions where id=v_result.current_revision_id for update;
 if not exists(select 1 from public.result_confirmations where result_revision_id=v_revision.id and side=1)or not exists(select 1 from public.result_confirmations where result_revision_id=v_revision.id and side=2)then raise exception using errcode='P0001',detail='CONFIRMATION_REQUIRED';end if;
 if exists(select 1 from public.match_participants mp where mp.match_id=v_match.id and not exists(select 1 from public.accounts a where a.player_id=mp.player_id and a.contact_verified_at is not null))then raise exception using errcode='P0001',detail='PLAYER_NOT_VERIFIED';end if;
 if v_match.record_class='ranked' then if not exists(select 1 from public.clubs c where c.id=v_match.club_id and c.subscription_status in('trialing','active')and(c.subscription_valid_until is null or c.subscription_valid_until>now()))then raise exception using errcode='P0001',detail='SUBSCRIPTION_INACTIVE';end if;if exists(select 1 from public.match_participants mp where mp.match_id=v_match.id and not public.player_ranked_eligible(mp.player_id,v_match.club_id))then raise exception using errcode='P0001',detail='IDENTITY_NOT_ATTESTED';end if;end if;
 v_calc:=nextval('private.competition_calculation_version');v_checksum:=encode(extensions.digest(v_revision.score::text||'|'||v_match.id::text||'|elo-v1','sha256'),'hex');
 insert into public.official_results(match_id,club_id,authoritative_revision_id,effect_state,finalized_by,eligibility_evidence,calculation_version,calculation_checksum)values(v_match.id,v_match.club_id,v_revision.id,case when v_match.record_class='ranked' then 'active'::public.ranked_effect_state else 'none'::public.ranked_effect_state end,v_actor,jsonb_build_object('contactVerified',true,'rankedAttested',v_match.record_class='ranked','subscriptionCheckedAt',now()),v_calc,v_checksum)returning id into v_official;
 update public.result_revisions set status='accepted' where id=v_revision.id;update public.match_results set status='finalized',version=version+1 where id=v_result.id returning public.match_results.version into version;update public.matches set status='finalized',completed_at=now(),version=public.matches.version+1 where id=v_match.id;
 if v_match.record_class='ranked' then
  select avg(coalesce(s.rating,1500)) into v_team_a from public.match_participants mp left join public.player_statistics s on s.player_id=mp.player_id where mp.match_id=v_match.id and mp.side=1;select avg(coalesce(s.rating,1500)) into v_team_b from public.match_participants mp left join public.player_statistics s on s.player_id=mp.player_id where mp.match_id=v_match.id and mp.side=2;v_delta:=private.elo_delta_v1(v_team_a,v_team_b,v_revision.winner_side);
  for v_player in select mp.player_id,mp.side from public.match_participants mp where mp.match_id=v_match.id order by mp.player_id for update loop
   insert into public.player_statistics(player_id)values(v_player.player_id)on conflict(player_id)do nothing;select * into v_stats from public.player_statistics where player_id=v_player.player_id for update;v_pre:=v_stats.rating;v_won:=v_player.side=v_revision.winner_side;v_post:=v_pre+case when v_player.side=1 then v_delta else -v_delta end;
   insert into private.rating_ledger(official_result_id,club_id,player_id,rule_version,pre_rating,expected,delta,post_rating)values(v_official,v_match.club_id,v_player.player_id,'elo-v1',v_pre,case when v_player.side=1 then private.elo_expected(v_team_a,v_team_b)else private.elo_expected(v_team_b,v_team_a)end,v_post-v_pre,v_post);
   update public.player_statistics set rating=v_post,wins=wins+case when v_won then 1 else 0 end,losses=losses+case when v_won then 0 else 1 end,current_streak=case when v_won then greatest(1,case when current_streak>0 then current_streak+1 else 1 end)else least(-1,case when current_streak<0 then current_streak-1 else -1 end)end,longest_win_streak=case when v_won then greatest(longest_win_streak,case when current_streak>0 then current_streak+1 else 1 end)else longest_win_streak end,last_match_at=now(),calculation_version=v_calc,updated_at=now() where player_id=v_player.player_id returning * into v_stats;
   insert into public.leaderboard_entries(scope,club_id,player_id,rating,wins,losses,win_rate,current_streak,longest_win_streak,last_match_at,calculation_version)values('overall',null,v_player.player_id,v_stats.rating,v_stats.wins,v_stats.losses,case when v_stats.wins+v_stats.losses=0 then 0 else v_stats.wins::numeric/(v_stats.wins+v_stats.losses)end,v_stats.current_streak,v_stats.longest_win_streak,v_stats.last_match_at,v_calc)on conflict(scope,club_id,player_id)do update set rating=excluded.rating,wins=excluded.wins,losses=excluded.losses,win_rate=excluded.win_rate,current_streak=excluded.current_streak,longest_win_streak=excluded.longest_win_streak,last_match_at=excluded.last_match_at,calculation_version=excluded.calculation_version;
   insert into public.leaderboard_entries(scope,club_id,player_id,rating,wins,losses,win_rate,current_streak,longest_win_streak,last_match_at,calculation_version)values('club',v_match.club_id,v_player.player_id,v_post,case when v_won then 1 else 0 end,case when v_won then 0 else 1 end,case when v_won then 1 else 0 end,case when v_won then 1 else -1 end,case when v_won then 1 else 0 end,now(),v_calc)on conflict(scope,club_id,player_id)do update set rating=public.leaderboard_entries.rating+(v_post-v_pre),wins=public.leaderboard_entries.wins+case when v_won then 1 else 0 end,losses=public.leaderboard_entries.losses+case when v_won then 0 else 1 end,win_rate=(public.leaderboard_entries.wins+case when v_won then 1 else 0 end)::numeric/(public.leaderboard_entries.wins+public.leaderboard_entries.losses+1),current_streak=case when v_won then greatest(1,public.leaderboard_entries.current_streak+1)else least(-1,public.leaderboard_entries.current_streak-1)end,longest_win_streak=case when v_won then greatest(public.leaderboard_entries.longest_win_streak,public.leaderboard_entries.current_streak+1)else public.leaderboard_entries.longest_win_streak end,last_match_at=excluded.last_match_at,calculation_version=v_calc;
  end loop;insert into private.calculation_events(official_result_id,rule_version,input_checksum,output_checksum,calculation_version)values(v_official,'elo-v1',v_checksum,encode(extensions.digest((select string_agg(player_id::text||':'||post_rating::text,',' order by player_id)from private.rating_ledger where official_result_id=v_official),'sha256'),'hex'),v_calc);
 end if;
 update public.match_participants set active=false where match_id=v_match.id;update public.event_courts set status='available',current_match_id=null,version=public.event_courts.version+1 where current_match_id=v_match.id;insert into private.audit_log(actor_auth_user_id,action,aggregate_type,aggregate_id,club_id,after_state)values(auth.uid(),'result.finalized','official_result',v_official,v_match.club_id,jsonb_build_object('calculationVersion',v_calc,'checksum',v_checksum));result_id:=v_result.id;official_result_id:=v_official;calculation_version:=v_calc;return next;
end$$;
revoke all on function private.finalize_match_result(uuid)from public,anon,authenticated;

create or replace function public.submit_match_result(p_match_id uuid,p_score jsonb,p_idempotency_key uuid)returns table(result_id uuid,revision_id uuid,status text,version bigint)language plpgsql security definer set search_path=pg_catalog,public,private as $$declare v_actor uuid:=public.current_player_id();v_match public.matches%rowtype;v_result uuid;v_revision uuid;v_wins_a int;v_wins_b int;v_digest text;begin if v_actor is null then raise exception using errcode='P0001',detail='AUTH_REQUIRED';end if;select * into v_match from public.matches where id=p_match_id for update;if v_match.id is null then raise exception using errcode='P0001',detail='NOT_FOUND';end if;if v_match.status not in('assigned','playing','score_pending')then raise exception using errcode='P0001',detail='INVALID_STATE_TRANSITION';end if;if not exists(select 1 from public.match_participants where match_id=p_match_id and player_id=v_actor)and not private.has_club_role(v_match.club_id,array['owner','score_official']::public.club_role[])then raise exception using errcode='P0001',detail='PERMISSION_DENIED';end if;if jsonb_typeof(p_score->'games')<>'array'or jsonb_array_length(p_score->'games')not between 1 and 5 or exists(select 1 from jsonb_array_elements(p_score->'games')g where not(g?'sideA'and g?'sideB')or(g->>'sideA')::int=(g->>'sideB')::int)then raise exception using errcode='P0001',detail='INVALID_SCORE';end if;select count(*)filter(where(g->>'sideA')::int>(g->>'sideB')::int),count(*)filter(where(g->>'sideB')::int>(g->>'sideA')::int)into v_wins_a,v_wins_b from jsonb_array_elements(p_score->'games')g;if v_wins_a=v_wins_b then raise exception using errcode='P0001',detail='INVALID_SCORE';end if;select rr.result_id,rr.id,'pending_confirmation',r.version into result_id,revision_id,status,version from public.result_revisions rr join public.match_results r on r.id=rr.result_id where rr.submitted_by=v_actor and rr.request_id=p_idempotency_key;if result_id is not null then return next;return;end if;insert into public.match_results(match_id,club_id,event_id)values(p_match_id,v_match.club_id,v_match.event_id)on conflict(match_id)do update set updated_at=now()returning id into v_result;v_digest:=encode(extensions.digest(p_score::text,'sha256'),'hex');insert into public.result_revisions(result_id,match_id,revision_no,score,score_digest,winner_side,submitted_by,request_id)values(v_result,p_match_id,(select coalesce(max(revision_no),0)+1 from public.result_revisions where result_id=v_result),p_score,v_digest,case when v_wins_a>v_wins_b then 1 else 2 end,v_actor,p_idempotency_key)returning id into v_revision;update public.match_results set current_revision_id=v_revision,status='pending_confirmation',version=public.match_results.version+1 where id=v_result returning public.match_results.version into version;update public.matches set status='score_pending',version=public.matches.version+1 where id=p_match_id;insert into private.audit_log(actor_auth_user_id,action,aggregate_type,aggregate_id,club_id,request_id,after_state)values(auth.uid(),'result.submitted','match_result',v_result,v_match.club_id,p_idempotency_key,jsonb_build_object('revisionId',v_revision,'scoreDigest',v_digest));result_id:=v_result;revision_id:=v_revision;status:='pending_confirmation';return next;end$$;

create or replace function public.confirm_match_result(p_result_id uuid,p_revision_id uuid,p_idempotency_key uuid)returns table(result_id uuid,status text,confirmed_side_a boolean,confirmed_side_b boolean,calculation_version bigint,version bigint)language plpgsql security definer set search_path=pg_catalog,public,private as $$declare v_actor uuid:=public.current_player_id();v_result public.match_results%rowtype;v_revision public.result_revisions%rowtype;v_side smallint;v_final record;begin select * into v_result from public.match_results where id=p_result_id for update;if v_result.id is null then raise exception using errcode='P0001',detail='NOT_FOUND';end if;if v_result.current_revision_id<>p_revision_id then raise exception using errcode='P0001',detail='REVISION_STALE';end if;select * into v_revision from public.result_revisions where id=p_revision_id;select mp.side into v_side from public.match_participants mp where mp.match_id=v_result.match_id and mp.player_id=v_actor;if v_side is null then raise exception using errcode='P0001',detail='PERMISSION_DENIED';end if;insert into public.result_confirmations(result_revision_id,player_id,side,score_digest,request_id)values(p_revision_id,v_actor,v_side,v_revision.score_digest,p_idempotency_key)on conflict(result_revision_id,player_id)do nothing;select exists(select 1 from public.result_confirmations where result_revision_id=p_revision_id and side=1),exists(select 1 from public.result_confirmations where result_revision_id=p_revision_id and side=2)into confirmed_side_a,confirmed_side_b;if confirmed_side_a and confirmed_side_b then select * into v_final from private.finalize_match_result(p_result_id);end if;select r.status::text,r.version,o.calculation_version into status,version,calculation_version from public.match_results r left join public.official_results o on o.match_id=r.match_id where r.id=p_result_id;result_id:=p_result_id;return next;end$$;
revoke all on function public.submit_match_result(uuid,jsonb,uuid),public.confirm_match_result(uuid,uuid,uuid)from public;grant execute on function public.submit_match_result(uuid,jsonb,uuid),public.confirm_match_result(uuid,uuid,uuid)to authenticated;
